  "claim": {
    "component_id": "C025.component",
    "value": "Compatible links can support a bounded account that an individual order had documented approval before placement despite a missing attachment, provided the evidence satisfies the internal rule.",
    "scope": "Conditional and order-specific. The rule's evidentiary sufficiency criteria are unspecified; compatibility alone does not establish their satisfaction.",
    "provenance": {
      "refs": [
        {
          "source_id": "P019",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span states the individual, bounded conclusion and expressly conditions it on evidence satisfying the internal rule."
    }
  },
  "signal_basis": {
    "component_id": "C025.signal_basis",
    "value": "Cross-checked, independently originating records agree on the order, the approver's authority, approval scope and documented approval before placement, with approval timing distinguished from documentation creation and upload timing.",
    "scope": "Assumed findings for the particular order, although the mapping presents them as prospective checks. Derivative records do not count as independent corroboration, and retrospective accounts or upload timestamps alone do not establish contemporaneous documentation or approval timing.",
